+		(lower.includes("case") ? 0.5 : 0.1) +
+		(lower.includes("follow") ? 0.4 : 0) +
+		(lower.includes("paid") ? 0.2 : 0);
+	return [a || 0.01, b || 0.01, ...Array.from({ length: 1534 }, () => 0)];
+}
